const checkBank = {};
Object.keys(taskBank).forEach(k=>{
  checkBank[k]=taskBank[k].filter(t=>t.type==='single'||t.type==='case'||t.type==='multi').map((t,i)=>({
    id:'c'+k+'-'+i,type:t.type==='case'?'single':t.type,prompt:t.prompt,options:t.options,answer:t.answer,why:t.why,refs:t.refs
  }));
});

const saved=JSON.parse(localStorage.getItem('gmu_const_v6')||'{}');
const state={
  viewed:new Set(saved.viewed||[]),
  doneTasks:saved.doneTasks||{},
  doneCases:saved.doneCases||{},
  scores:saved.scores||{},
  sound:saved.sound!==false
};
let currentModule=null,currentTab='learn',blockIndex=0,currentTask=null,caseIndex=0,checkState=null;

function save(){localStorage.setItem('gmu_const_v6',JSON.stringify({viewed:[...state.viewed],doneTasks:state.doneTasks,doneCases:state.doneCases,scores:state.scores,sound:state.sound}))}
function targetsFor(id){return targets.filter(t=>t.chapter===id)}
function mLabel(id){return id===0?'Преамбула':id===10?'Раздел II':'Глава '+id}
function modulePct(id){
  const total=(taskBank[id]?.length||0)+(caseBank[id]?.length||0)+(checkBank[id]?.length||0);
  const done=(state.doneTasks[id]?.length||0)+(state.doneCases[id]?.length||0)+(state.scores[id]!==undefined?(checkBank[id]?.length||0):0);
  return total?Math.round(done/total*100):0
}
function showPage(id){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===id))}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1500)}
function toggleSound(){state.sound=!state.sound;save();syncSoundButton()}
function syncSoundButton(){const b=document.getElementById('soundBtn');b.classList.toggle('active',state.sound);b.textContent=state.sound?'🔊 Звук':'🔇 Звук'}
function tone(freq,start,dur,type='sine',vol=.04){
  if(!state.sound)return;
  try{
    const ac=window.__gmuAudio||(window.__gmuAudio=new (window.AudioContext||window.webkitAudioContext)());
    const o=ac.createOscillator(),g=ac.createGain();
    o.type=type;o.frequency.setValueAtTime(freq,ac.currentTime+start);
    g.gain.setValueAtTime(.0001,ac.currentTime+start);
    g.gain.exponentialRampToValueAtTime(vol,ac.currentTime+start+.01);
    g.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+start+dur);
    o.connect(g);g.connect(ac.destination);o.start(ac.currentTime+start);o.stop(ac.currentTime+start+dur+.02)
  }catch(e){}
}
function successSound(){tone(523,0,.11,'triangle',.05);tone(659,.08,.13,'triangle',.05);tone(784,.17,.16,'sine',.05);tone(1047,.28,.10,'sine',.03)}
function errorSound(){tone(220,0,.13,'sawtooth',.025);tone(165,.10,.17,'triangle',.035)}

function renderHome(){
  const g=document.getElementById('modules');g.innerHTML='';
  chapters.forEach(ch=>{
    const p=modulePct(ch.id),b=document.createElement('button');
    b.className='moduleCard';b.style.setProperty('--accent',ch.accent);
    b.innerHTML='<div class="cardTop"><div class="num">'+(ch.id===0?'§':ch.id===10?'II':String(ch.id).padStart(2,'0'))+'</div><div class="range">'+ch.range+'</div></div>'+
      '<h3>'+ch.name+'</h3><p>'+moduleInfo[ch.id].desc+'</p><div class="bar"><span style="width:'+p+'%"></span></div>'+
      '<div class="cardFoot"><span>'+p+'% освоено</span><span>'+taskBank[ch.id].length+' уникальных заданий</span></div>';
    b.onclick=()=>openModule(ch.id);g.appendChild(b)
  });
  document.getElementById('globalProgress').textContent=state.viewed.size+' / '+targets.length+' норм просмотрено';
  syncSoundButton()
}
function showHome(){currentModule=null;document.getElementById('crumb').textContent='Разделы Конституции';renderHome();showPage('home')}
function openModule(id){
  currentModule=id;currentTab='learn';blockIndex=0;currentTask=null;caseIndex=0;checkState=null;
  const ch=chapters.find(x=>x.id===id);
  document.getElementById('crumb').textContent=mLabel(id)+' · '+ch.name;
  document.getElementById('courseKicker').textContent=mLabel(id);
  document.getElementById('courseTitle').textContent=ch.name;
  document.getElementById('courseDesc').textContent=moduleInfo[id].desc;
  document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab==='learn'));
  updateProgress();renderTab();showPage('course')
}
function updateProgress(){const p=modulePct(currentModule);document.getElementById('coursePct').textContent=p+'%';document.getElementById('courseBar').style.width=p+'%'}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{currentTab=b.dataset.tab;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));renderTab()});
function renderTab(){if(currentTab==='learn')renderLearn();else if(currentTab==='scheme')renderScheme();else if(currentTab==='practice')renderPractice();else if(currentTab==='cases')renderCases();else renderCheck()}

function renderLearn(){
  const inf=moduleInfo[currentModule],bl=inf.blocks[blockIndex],ids=bl[3]||[],panel=document.getElementById('panel');
  ids.forEach(id=>state.viewed.add(id));save();
  panel.innerHTML='<div class="learn"><aside class="rail"><div><div class="eyebrow">Смысловые блоки</div><h3>Разобраться</h3><p>Номер статьи здесь только источник. Сначала — идея и механизм.</p></div><div class="clusterList" id="clusterList"></div></aside>'+
    '<div class="learnMain"><div class="bigIdea"><div><div class="eyebrow">'+mLabel(currentModule)+'</div><h3>'+bl[0]+'</h3><p>'+bl[1]+'</p></div><span class="refs">'+bl[2]+'</span></div><div class="normGrid" id="normGrid"></div>'+
    '<div class="note">Смысловой конспект не заменяет официальный текст Конституции. Номер нормы показывается как источник, но не является объектом запоминания.</div></div></div>';
  const list=document.getElementById('clusterList');
  inf.blocks.forEach((x,i)=>{const b=document.createElement('button');b.className='clusterBtn'+(i===blockIndex?' active':'');b.innerHTML='<b>'+x[0]+'</b><span>'+x[2]+'</span>';b.onclick=()=>{blockIndex=i;renderLearn()};list.appendChild(b)});
  const grid=document.getElementById('normGrid');
  let arr=ids.map(id=>targets.find(t=>t.id===id)).filter(Boolean);if(!arr.length)arr=targetsFor(currentModule).slice(0,8);
  arr.forEach(t=>{state.viewed.add(t.id);const d=document.createElement('div');d.className='norm';d.innerHTML='<b>'+t.label+'</b><p>'+t.topic+'</p>';grid.appendChild(d)});
  save();renderHome()
}
function renderScheme(){
  const d=moduleInfo[currentModule].diagram,p=document.getElementById('panel');let body='';
  if(d.kind==='flow'){
    body='<div class="flow">'+d.nodes.map((n,i)=>'<div class="flowNode"><div class="ico">'+n[0]+'</div><b>'+n[1]+'</b><span>'+n[2]+'</span></div>'+(i<d.nodes.length-1?'<div class="arrow">→</div>':'')).join('')+'</div>'
  } else {
    body='<div class="lanes">'+d.lanes.map(l=>'<div class="lane"><h4>'+l[0]+'</h4>'+l[1].map(x=>'<div>'+x+'</div>').join('')+'</div>').join('')+'</div>'
  }
  p.innerHTML='<div class="schemeWrap"><aside class="schemeInfo"><div class="eyebrow">Визуальная модель</div><h3>'+d.title+'</h3><p>'+d.caption+'</p></aside><div class="schemeStage">'+body+'</div></div>'
}
function remainingTasks(){const done=new Set(state.doneTasks[currentModule]||[]);return taskBank[currentModule].filter(t=>!done.has(t.id))}
function renderPractice(){
  const rem=remainingTasks(),panel=document.getElementById('panel');
  if(!currentTask&&rem.length)currentTask=rem[0];
  if(!currentTask){
    panel.innerHTML='<div class="finish"><div><div class="score">✓</div><h3>Все уникальные задания пройдены</h3><p>Автоматических повторов нет. Второй круг запускается только вручную.</p><div class="row"><button class="btn ghost" onclick="restartPractice()">Начать второй круг</button><button class="btn primary" onclick="switchTab(\'check\')">К итогу →</button></div></div></div>';return
  }
  const total=taskBank[currentModule].length,done=state.doneTasks[currentModule]?.length||0;
  panel.innerHTML='<div class="practice"><div class="taskArea"><div class="taskMeta"><span class="tag">'+currentTask.label+'</span><span class="count">'+(done+1)+' / '+total+'</span></div>'+
    '<div class="taskPrompt">'+currentTask.prompt+'</div><div class="taskSub">Номер нормы вспоминать не нужно: после решения вы увидите правовое основание.</div><div class="answerZone" id="answerZone"></div>'+
    '<div class="feedback" id="feedback">Решите задачу. Ошибка не закрывает попытку.</div></div>'+
    '<aside class="taskSide"><div><div class="eyebrow">Без повторов</div><h3>Уникальная очередь</h3><p>Каждое задание этого раздела появляется один раз.</p></div><div class="doneBox"><b>'+done+' / '+total+'</b>заданий завершено</div>'+
    '<div class="taskDots">'+taskBank[currentModule].map(t=>'<div class="taskDot '+((state.doneTasks[currentModule]||[]).includes(t.id)?'done ':'')+(t.id===currentTask.id?'current':'')+'"></div>').join('')+'</div><button class="btn ghost" onclick="switchTab(\'scheme\')">Посмотреть схему</button></aside></div>';
  renderTaskInput(currentTask)
}
function restartPractice(){state.doneTasks[currentModule]=[];currentTask=null;save();updateProgress();renderPractice()}
function switchTab(tab){currentTab=tab;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));renderTab()}
function renderTaskInput(t){
  const z=document.getElementById('answerZone');z.innerHTML='';
  if(t.type==='single'||t.type==='case'||t.type==='multi'){
    const a=document.createElement('div');a.className='answers';
    t.options.forEach((o,i)=>{const text=Array.isArray(o)?o[0]:o,b=document.createElement('button');b.className='ans';b.dataset.i=i;b.innerHTML='<span class="letter">'+('ABCD'[i]||'•')+'</span><span>'+text+'</span>';b.onclick=()=>t.type==='multi'?b.classList.toggle('selected'):answerSingle(i,b);a.appendChild(b)});
    if(t.type==='multi'){const c=document.createElement('button');c.className='btn primary check';c.textContent='Проверить выбранные';c.onclick=answerMulti;a.appendChild(c)}
    z.appendChild(a);return
  }
  if(t.type==='match'){
    const g=document.createElement('div');g.className='matchGrid';const rights=t.pairs.map(p=>p[1]);
    t.pairs.forEach((p,i)=>{const r=document.createElement('div');r.className='matchRow';r.innerHTML='<div class="matchLeft">'+p[0]+'</div><div class="matchArrow">→</div><select class="matchSelect" data-i="'+i+'"><option value="">Выберите…</option>'+rights.map(x=>'<option value="'+encodeURIComponent(x)+'">'+x+'</option>').join('')+'</select>';g.appendChild(r)});
    const c=document.createElement('button');c.className='btn primary check';c.textContent='Проверить сопоставление';c.onclick=answerMatch;g.appendChild(c);z.appendChild(g);return
  }
  if(t.type==='order'){
    const order=t.steps.map((x,i)=>({id:String(i),text:x})).sort(()=>Math.random()-.5);if(order.every((x,i)=>x.id===String(i)))order.reverse();
    const g=document.createElement('div');g.className='orderList';g.id='orderList';
    order.forEach(x=>{const r=document.createElement('div');r.className='orderItem';r.dataset.id=x.id;r.innerHTML='<div class="orderNum">•</div><span>'+x.text+'</span><div><button class="move" onclick="moveOrder(\''+x.id+'\',-1)">↑</button> <button class="move" onclick="moveOrder(\''+x.id+'\',1)">↓</button></div>';g.appendChild(r)});
    const c=document.createElement('button');c.className='btn primary check';c.textContent='Проверить порядок';c.onclick=answerOrder;g.appendChild(c);z.appendChild(g);renumberOrder();return
  }
  if(t.type==='classify'){
    const g=document.createElement('div');g.className='matchGrid';
    t.items.forEach((it,i)=>{const r=document.createElement('div');r.className='matchRow';r.innerHTML='<div class="matchLeft">'+it[0]+'</div><div class="matchArrow">→</div><select class="matchSelect" data-i="'+i+'"><option value="">Выберите…</option>'+t.groups.map(gr=>'<option value="'+gr[0]+'">'+gr[1]+'</option>').join('')+'</select>';g.appendChild(r)});
    const c=document.createElement('button');c.className='btn primary check';c.textContent='Проверить распределение';c.onclick=answerClassify;g.appendChild(c);z.appendChild(g)
  }
}
function fail(msg,el){errorSound();if(el&&el.classList)el.classList.add('wrong');document.getElementById('feedback').innerHTML='<b>Не получилось.</b> '+msg+' Попробуйте ещё раз — правильный вариант не раскрывается автоматически.';if(el&&el.classList)setTimeout(()=>el.classList.remove('wrong'),500)}
function succeed(el){
  successSound();if(el&&el.classList)el.classList.add('correct');
  document.getElementById('feedback').innerHTML='<b>Верно.</b> '+currentTask.why+' <span class="refs">Основание: '+currentTask.refs+'</span>';
  if(!state.doneTasks[currentModule])state.doneTasks[currentModule]=[];
  if(!state.doneTasks[currentModule].includes(currentTask.id))state.doneTasks[currentModule].push(currentTask.id);
  save();updateProgress();setTimeout(()=>{currentTask=null;renderPractice()},1100)
}
function answerSingle(i,b){i===currentTask.answer?succeed(b):fail('Выбранный вывод не следует из конституционной логики ситуации.',b)}
function answerMulti(){
  const got=[...document.querySelectorAll('.ans.selected')].map(x=>+x.dataset.i).sort((a,b)=>a-b);
  const need=currentTask.options.map((o,i)=>Array.isArray(o)&&o[1]?i:null).filter(x=>x!==null);
  got.length===need.length&&got.every((x,i)=>x===need[i])?succeed(document.querySelector('.check')):fail('Набор неполный или содержит лишний вариант.',document.querySelector('.check'))
}
function answerMatch(){
  const s=[...document.querySelectorAll('.matchSelect')];let ok=true;
  s.forEach((x,i)=>{const v=x.value?decodeURIComponent(x.value):'',good=v===currentTask.pairs[i][1];x.classList.toggle('bad',!good);if(!good)ok=false});
  ok?succeed():fail('Есть неверные соответствия.',null)
}
function moveOrder(id,d){
  const g=document.getElementById('orderList'),rows=[...g.querySelectorAll('.orderItem')],el=rows.find(x=>x.dataset.id===id),i=rows.indexOf(el),j=i+d;
  if(j<0||j>=rows.length)return;if(d<0)g.insertBefore(el,rows[j]);else g.insertBefore(rows[j],el);renumberOrder()
}
function renumberOrder(){document.querySelectorAll('#orderList .orderItem').forEach((x,i)=>x.querySelector('.orderNum').textContent=i+1)}
function answerOrder(){
  const got=[...document.querySelectorAll('#orderList .orderItem')].map(x=>x.dataset.id),ok=got.every((x,i)=>x===String(i));
  document.querySelectorAll('#orderList .orderItem').forEach((x,i)=>x.classList.toggle('bad',got[i]!==String(i)));
  ok?succeed():fail('Этапы стоят не в той последовательности.',null)
}
function answerClassify(){
  const s=[...document.querySelectorAll('.matchSelect')];let ok=true;
  s.forEach((x,i)=>{const good=x.value===currentTask.items[i][1];x.classList.toggle('bad',!good);if(!good)ok=false});
  ok?succeed():fail('Часть позиций попала не в ту категорию.',null)
}

function renderCases(){
  const bank=caseBank[currentModule]||[],c=bank[caseIndex%bank.length],panel=document.getElementById('panel');
  const scene=c.scene.map((n,i)=>'<div class="sceneActor"><div class="ico">'+n[0]+'</div><b>'+n[1]+'</b></div>'+(i<c.scene.length-1?'<div class="arrow">→</div>':'')).join('');
  panel.innerHTML='<div class="caseLayout"><aside class="caseVisual"><div><div class="eyebrow">Кейс '+(caseIndex+1)+' из '+bank.length+'</div><h3>'+c.title+'</h3><p>Схема показывает участников и конфликт, а не просто украшает карточку.</p></div><div class="scene">'+scene+'</div><div class="caseNav">'+bank.map((_,i)=>'<button class="'+(i===caseIndex?'active':'')+'" onclick="caseIndex='+i+';renderCases()"></button>').join('')+'</div></aside>'+
    '<div class="caseTask"><div class="tag">'+c.refs+'</div><div class="story">'+c.story+'</div><div class="caseQuestion">'+c.question+'</div><div class="answers" id="caseAnswers"></div><div class="caseExplain" id="caseExplain"></div></div></div>';
  const a=document.getElementById('caseAnswers');
  c.options.forEach((x,i)=>{const b=document.createElement('button');b.className='ans';b.innerHTML='<span class="letter">'+('ABCD'[i])+'</span><span>'+x+'</span>';b.onclick=()=>{document.querySelectorAll('#caseAnswers .ans').forEach(y=>y.disabled=true);const e=document.getElementById('caseExplain');e.style.display='block';if(i===c.answer){successSound();b.classList.add('correct');e.innerHTML='<b>Верно.</b> '+c.why+' <span class="refs">Основание: '+c.refs+'</span>';if(!state.doneCases[currentModule])state.doneCases[currentModule]=[];if(!state.doneCases[currentModule].includes(caseIndex))state.doneCases[currentModule].push(caseIndex);save();updateProgress()}else{errorSound();b.classList.add('wrong');e.innerHTML='<b>Нет.</b> '+c.why+' <span class="refs">Основание: '+c.refs+'</span>'}};a.appendChild(b)})
}
function renderCheck(){
  const bank=checkBank[currentModule]||[];
  if(!bank.length){document.getElementById('panel').innerHTML='<div class="finish"><div><div class="score">—</div><h3>Итоговый блок ещё не готов</h3></div></div>';return}
  if(!checkState){document.getElementById('panel').innerHTML='<div class="finish"><div><div class="score">'+bank.length+'</div><h3>Итоговый контроль раздела</h3><p>Здесь только смысловые вопросы. Номера статей даны как источник.</p><div class="row"><button class="btn primary" onclick="startCheck()">Начать →</button></div></div></div>';return}
  if(checkState.i>=bank.length){
    const score=Math.round(checkState.correct/bank.length*100);state.scores[currentModule]=Math.max(state.scores[currentModule]||0,score);save();updateProgress();if(score>=70)successSound();else errorSound();
    document.getElementById('panel').innerHTML='<div class="finish"><div><div class="score">'+score+'%</div><h3>'+checkState.correct+' из '+bank.length+'</h3><p>Попытка завершена без повторов.</p><div class="row"><button class="btn ghost" onclick="checkState=null;renderCheck()">Назад</button><button class="btn primary" onclick="startCheck()">Новая попытка</button></div></div></div>';return
  }
  const q=bank[checkState.i],opts=q.type==='multi'?q.options.map(x=>x[0]):q.options;
  document.getElementById('panel').innerHTML='<div class="practice"><div class="taskArea"><div class="taskMeta"><span class="tag">Итог · '+q.refs+'</span><span class="count">'+(checkState.i+1)+' / '+bank.length+'</span></div><div class="taskPrompt">'+q.prompt+'</div><div class="taskSub">Оценивается понимание смысла, а не номер статьи.</div><div class="answerZone"><div class="answers" id="checkAnswers"></div></div><div class="feedback">Ответ фиксируется с первой попытки.</div></div></div>';
  const a=document.getElementById('checkAnswers');
  opts.forEach((x,i)=>{const b=document.createElement('button');b.className='ans';b.dataset.i=i;b.innerHTML='<span class="letter">'+('ABCD'[i])+'</span><span>'+x+'</span>';b.onclick=()=>q.type==='multi'?b.classList.toggle('selected'):submitCheckSingle(i);a.appendChild(b)});
  if(q.type==='multi'){const b=document.createElement('button');b.className='btn primary check';b.textContent='Зафиксировать ответ';b.onclick=submitCheckMulti;a.appendChild(b)}
}
function startCheck(){checkState={i:0,correct:0};renderCheck()}
function advanceCheck(ok){if(ok){checkState.correct++;successSound()}else errorSound();checkState.i++;setTimeout(renderCheck,300)}
function submitCheckSingle(i){advanceCheck(i===checkBank[currentModule][checkState.i].answer)}
function submitCheckMulti(){
  const q=checkBank[currentModule][checkState.i],got=[...document.querySelectorAll('#checkAnswers .ans.selected')].map(x=>+x.dataset.i).sort((a,b)=>a-b),need=q.options.map((o,i)=>o[1]?i:null).filter(x=>x!==null);
  advanceCheck(got.length===need.length&&got.every((x,i)=>x===need[i]))
}

renderHome();syncSoundButton();
